#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES — 生产 RC 引导（主机修改需逐阶段确认；密钥只经 stdin 写入 ECS）
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ENV_FILE="${RB_ENV_FILE:-deploy/.env.acceptance}"
SSH_OPTS=(-o ConnectTimeout=10 -o BatchMode=yes)
SCP_OPTS=(-o ConnectTimeout=10 -o BatchMode=yes)

remote() { ssh "${SSH_OPTS[@]}" "$ECS_SSH" "$@"; }
remote_write() { ssh "${SSH_OPTS[@]}" "$ECS_SSH" "umask 077; cat > '$1'"; }
sql_quote() { printf '%s' "${1//\'/\'\'}"; }

banner "云河FC 生产 RC 引导"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "ECS 与目标确认"
ask RC_DOMAIN "生产域名（不含 www）[yunhefc.com]："
RC_DOMAIN="${RC_DOMAIN:-yunhefc.com}"
ask ECS_SSH "ECS SSH 目标 [root@47.116.72.163]："
ECS_SSH="${ECS_SSH:-root@47.116.72.163}"
ECS_IP="${ECS_SSH#*@}"
if remote 'echo ok' >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} SSH 可用：$ECS_SSH"
else
  warn "SSH 不可用，后续阶段无法继续"; SKIPPED+=("ECS SSH $ECS_SSH")
fi
remote 'docker --version && docker compose version' 2>/dev/null | sed 's/^/  /' || warn "Docker/Compose 未就绪"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "DNS：www / admin / api"
open_url "https://dns.console.aliyun.com/"
step "确认 www.$RC_DOMAIN 已指向 $ECS_IP；为 admin 与 api 各添加一条 A 记录 → $ECS_IP。"
pause "添加完成后回车，向导会检查解析"
dns_ok=0
for _ in $(seq 1 12); do
  a=$(dig +short "admin.$RC_DOMAIN" | head -n1)
  b=$(dig +short "api.$RC_DOMAIN" | head -n1)
  if [[ -n "$a" && -n "$b" ]]; then dns_ok=1; break; fi
  sleep 5
done
if (( dns_ok )); then
  say "  ${GREEN}✓${RESET} admin/api 已解析"
else
  warn "admin/api 仍未解析；可稍后重跑向导"; SKIPPED+=("DNS admin/api A 记录")
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "TLS 证书"
say "需要覆盖 $RC_DOMAIN 的证书；nginx 固定读取 fullchain.pem / privkey.pem。"
ask CERT_FULLCHAIN "本地 fullchain.pem 路径："
ask CERT_PRIVKEY "本地 privkey.pem 路径："
if [[ -f "$CERT_FULLCHAIN" && -f "$CERT_PRIVKEY" ]]; then
  if openssl x509 -in "$CERT_FULLCHAIN" -noout -checkend 2592000 >/dev/null 2>&1; then
    say "  ${GREEN}✓${RESET} 证书剩余 >30 天"
  else
    warn "证书缺失或剩余 ≤30 天"
  fi
  if openssl x509 -in "$CERT_FULLCHAIN" -noout -text 2>/dev/null | grep -A1 'Subject Alternative Name' | grep -q "$RC_DOMAIN"; then
    say "  ${GREEN}✓${RESET} SAN 覆盖 $RC_DOMAIN"
  else
    warn "SAN 未覆盖 $RC_DOMAIN，浏览器会报证书错误"
  fi
  scp "${SCP_OPTS[@]}" "$CERT_FULLCHAIN" "$ECS_SSH:/opt/yunhefc/certs/fullchain.pem"
  scp "${SCP_OPTS[@]}" "$CERT_PRIVKEY" "$ECS_SSH:/opt/yunhefc/certs/privkey.pem"
  remote 'chown deploy:deploy /opt/yunhefc/certs/fullchain.pem /opt/yunhefc/certs/privkey.pem; chmod 644 /opt/yunhefc/certs/fullchain.pem; chmod 600 /opt/yunhefc/certs/privkey.pem'
  say "  ${GREEN}✓${RESET} 证书已上传到 /opt/yunhefc/certs"
else
  warn "证书文件不存在，跳过"; SKIPPED+=("TLS 证书上传")
fi
open_url "https://yundun.console.aliyun.com/?p=cas"
step "如无证书，可在数字证书管理服务申请 *.${RC_DOMAIN} 通配符证书后重跑本阶段。"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "ACR 镜像仓库"
ask ACR_REGISTRY "ACR registry [registry.cn-shanghai.aliyuncs.com]："
ACR_REGISTRY="${ACR_REGISTRY:-registry.cn-shanghai.aliyuncs.com}"
ask ACR_NAMESPACE "ACR namespace [zyc1013]："
ACR_NAMESPACE="${ACR_NAMESPACE:-zyc1013}"
ask ACR_USERNAME "只读拉取账号："
ask_secret ACR_PASSWORD "只读拉取密码："
ask SHA7 "要部署的 commit sha7 [ea92ad4]："
SHA7="${SHA7:-ea92ad4}"
{
  printf 'ACR_REGISTRY=%s\n' "$ACR_REGISTRY"
  printf 'ACR_NAMESPACE=%s\n' "$ACR_NAMESPACE"
  printf 'ACR_USERNAME=%s\n' "$ACR_USERNAME"
  printf 'ACR_PASSWORD=%s\n' "$ACR_PASSWORD"
} | remote_write /opt/yunhefc/env/acr.env
remote 'chown deploy:deploy /opt/yunhefc/env/acr.env; chmod 600 /opt/yunhefc/env/acr.env'
say "  ${GREEN}✓${RESET} 写入 /opt/yunhefc/env/acr.env (600)"
if printf '%s' "$ACR_PASSWORD" | remote "docker login '$ACR_REGISTRY' -u '$ACR_USERNAME' --password-stdin" >/dev/null 2>&1; then
  say "  ${GREEN}✓${RESET} ACR 登录成功"
else
  warn "ACR 登录失败"; SKIPPED+=("ACR 登录")
fi
for image in yunhefc-backend yunhefc-nginx; do
  if remote "docker manifest inspect '$ACR_REGISTRY/$ACR_NAMESPACE/$image:sha-$SHA7'" >/dev/null 2>&1; then
    say "  ${GREEN}✓${RESET} $image:sha-$SHA7 存在"
  else
    warn "$image:sha-$SHA7 不存在"; SKIPPED+=("镜像 $image:sha-$SHA7")
  fi
done

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "RDS：建库与账号分离"
ask RDS_HOST "RDS 主机："
ask RDS_PORT "RDS 端口 [3306]："
RDS_PORT="${RDS_PORT:-3306}"
ask RDS_ADMIN_USER "RDS 管理账号："
ask_secret RDS_ADMIN_PASSWORD "RDS 管理密码："
ask_secret RDS_MIGRATOR_PASSWORD "迁移账号新密码："
ask_secret RDS_APP_PASSWORD "应用账号新密码："
step "将创建 yunhefc 库，并把两个账号密码重置为本次输入。"
if confirm "确认执行（幂等，但会重置账号密码）？"; then
  printf 'MYSQL_PWD=%s\n' "$RDS_ADMIN_PASSWORD" | remote "umask 077; cat > /tmp/.rdsenv"
  sql=$(cat <<'SQL'
CREATE DATABASE IF NOT EXISTS yunhefc DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE USER IF NOT EXISTS 'yunhefc_migrator'@'%' IDENTIFIED BY '__MIGRATOR_PWD__';
ALTER USER 'yunhefc_migrator'@'%' IDENTIFIED BY '__MIGRATOR_PWD__';
CREATE USER IF NOT EXISTS 'yunhefc_app'@'%' IDENTIFIED BY '__APP_PWD__';
ALTER USER 'yunhefc_app'@'%' IDENTIFIED BY '__APP_PWD__';
GRANT ALL PRIVILEGES ON yunhefc.* TO 'yunhefc_migrator'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE ON yunhefc.* TO 'yunhefc_app'@'%';
FLUSH PRIVILEGES;
SQL
)
  sql=${sql//__MIGRATOR_PWD__/$(sql_quote "$RDS_MIGRATOR_PASSWORD")}
  sql=${sql//__APP_PWD__/$(sql_quote "$RDS_APP_PASSWORD")}
  if printf '%s\n' "$sql" | remote "docker run --rm -i --network host --env-file /tmp/.rdsenv mysql:8.4 mysql -h '$RDS_HOST' -P '$RDS_PORT' -u '$RDS_ADMIN_USER'" 2>/dev/null; then
    say "  ${GREEN}✓${RESET} RDS 库与账号已就绪"
  else
    warn "RDS 初始化失败"; SKIPPED+=("RDS 建库/账号")
  fi
  remote 'rm -f /tmp/.rdsenv'
else
  SKIPPED+=("RDS 建库/账号（未确认）")
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "生产 .env 与收尾核对"
ask_secret REDIS_PASSWORD "Redis 密码（留空自动生成）："
if [[ -z "$REDIS_PASSWORD" ]]; then REDIS_PASSWORD=$(openssl rand -hex 16); say "  ${DIM}已生成随机 Redis 密码${RESET}"; fi
ask_secret SMS_APPCODE "短信 APPCODE："
ask SMS_TEMPLATE_ID "短信模板 ID："
ask SMS_SIGN_ID "短信签名 ID："
ask WECHAT_APP_ID "微信 AppID："
ask_secret WECHAT_APP_SECRET "微信 AppSecret："
ask OSS_ENDPOINT "OSS Endpoint [https://oss-cn-shanghai.aliyuncs.com]："
OSS_ENDPOINT="${OSS_ENDPOINT:-https://oss-cn-shanghai.aliyuncs.com}"
ask OSS_BUCKET "OSS Bucket："
ask OSS_ACCESS_KEY_ID "OSS AccessKeyId："
ask_secret OSS_ACCESS_KEY_SECRET "OSS AccessKeySecret："

{
  printf 'DOMAIN=%s\n' "$RC_DOMAIN"
  printf 'PUBLIC_BASE_URL=https://www.%s\n' "$RC_DOMAIN"
  printf 'SESSION_COOKIE_SECURE=true\n'
  printf 'SESSION_COOKIE_DOMAIN=\n'
  printf 'CORS_ALLOWED_ORIGINS=https://www.%s,https://admin.%s\n' "$RC_DOMAIN" "$RC_DOMAIN"
  printf 'DB_URL=jdbc:mysql://%s:%s/yunhefc?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC&characterEncoding=utf8\n' "$RDS_HOST" "$RDS_PORT"
  printf 'DB_USERNAME=yunhefc_app\n'
  printf 'DB_PASSWORD=%s\n' "$RDS_APP_PASSWORD"
  printf 'REDIS_HOST=redis\n'
  printf 'REDIS_PORT=6379\n'
  printf 'REDIS_PASSWORD=%s\n' "$REDIS_PASSWORD"
  printf 'KAFKA_BOOTSTRAP_SERVERS=kafka:9092\n'
  printf 'SMS_MOCK_ENABLED=false\n'
  printf 'SMS_ENDPOINT=https://gyytz.market.alicloudapi.com/sms/smsSend\n'
  printf 'SMS_APPCODE=%s\n' "$SMS_APPCODE"
  printf 'SMS_TEMPLATE_ID=%s\n' "$SMS_TEMPLATE_ID"
  printf 'SMS_SIGN_ID=%s\n' "$SMS_SIGN_ID"
  printf 'WECHAT_ENABLED=true\n'
  printf 'WECHAT_MODE=real\n'
  printf 'WECHAT_APP_ID=%s\n' "$WECHAT_APP_ID"
  printf 'WECHAT_APP_SECRET=%s\n' "$WECHAT_APP_SECRET"
  printf 'WECHAT_CALLBACK_URL=https://www.%s/api/v1/c/auth/wechat/callback\n' "$RC_DOMAIN"
  printf 'WECHAT_ALLOWED_REDIRECT_PREFIXES=/\n'
  printf 'WECHAT_REQUIRE_UA=true\n'
  printf 'OSS_MODE=real\n'
  printf 'OSS_ENDPOINT=%s\n' "$OSS_ENDPOINT"
  printf 'OSS_BUCKET=%s\n' "$OSS_BUCKET"
  printf 'OSS_ACCESS_KEY_ID=%s\n' "$OSS_ACCESS_KEY_ID"
  printf 'OSS_ACCESS_KEY_SECRET=%s\n' "$OSS_ACCESS_KEY_SECRET"
  printf 'AUDIT_EXPORT_ENABLED=false\n'
} | remote_write /opt/yunhefc/.env
remote 'chown deploy:deploy /opt/yunhefc/.env; chmod 600 /opt/yunhefc/.env'
say "  ${GREEN}✓${RESET} 写入 /opt/yunhefc/.env (600)"

say "收尾核对："
remote 'ls -ld /opt/yunhefc /opt/yunhefc/certs /opt/yunhefc/env; ls -l /opt/yunhefc/.env /opt/yunhefc/env/acr.env /opt/yunhefc/certs/ 2>/dev/null' | sed 's/^/  /'
if remote "grep -q '__CHANGE_ME__' /opt/yunhefc/.env /opt/yunhefc/env/acr.env" 2>/dev/null; then
  warn "仍有 __CHANGE_ME__ 占位符"
else
  say "  ${GREEN}✓${RESET} 无占位符残留"
fi
say ""
say "下一步（迁移 + 首发）："
note "1. 在目标 commit 检出中复制 backend/src/main/resources/db/migration/*.sql 到 /opt/yunhefc/migrations/"
note "2. 用迁移账号执行 flyway migrate（RUNBOOK §1.3）"
note "3. 准备 /opt/yunhefc/releases/sha-$SHA7/ 的 compose 快照与 release.env"
note "4. /opt/yunhefc/bin/release.sh --sha $SHA7"
finish
